import csv,json,shutil
from pathlib import Path
R=Path(__file__).resolve().parent;P=R/'package';p=P/'DATA_DICTIONARY.csv'
meanings={'article_ids':'All DBAASP article record IDs merged into this normalized source entry','authors':'Reported bibliographic authors as database objects; not task participants','families':'Distinct descriptive sequence-family IDs linked to this source','journal':'Reported journal metadata object','measurement_row_ids':'Explicit row IDs in MEASUREMENT_SOURCE_INDEX.csv linked to this source','native_censor_eligible':'Ecoli-only frozen one-sided-bound label eligibility; not formal training admission','native_exclusions':'Frozen core exclusion reasons; non-Ecoli rows marked NOT_E_COLI','native_primary_point_eligible':'Ecoli-only frozen point label eligibility; not formal training admission','peptide_ids':'Distinct DBAASP peptide record IDs associated with this publication','pubmed_id':'Reported PubMed identifier; no independent article-content verification','pubmed_url':'Reported PubMed URL; included as text only, not fetched','source_family_component':'Frozen family-plus-publication connected-component ID for this measurement','source_family_components':'Distinct family-plus-publication component IDs for this source','source_key':'Normalized PMID or year+title source identifier; unresolved remains blank','title':'Reported bibliographic title, not a claim of verified measurement support','year':'Reported publication year'}
with p.open() as f:rd=csv.DictReader(f);fields=rd.fieldnames;rows=list(rd)
for row in rows:
 if row['table'] in ['SOURCE_INDEX.csv','MEASUREMENT_SOURCE_INDEX.csv'] and row['field'] in meanings:row['meaning']=meanings[row['field']]
with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
shutil.copyfile(R/'CLI_REPRODUCTION.json',P/'evidence/CLI_REPRODUCTION.json');shutil.copyfile(R/'PDF_CHECK.json',P/'evidence/PDF_CHECK.json')
(P/'evidence/BUILD_NOTES.json').write_text(json.dumps({'initial_PDF_layout_attempt':'Stopped before save by table-cell overflow assertion; numeric cells changed to Latin font, then one-page geometry passed.','PDF_symbol_revision':'Visual inspection found unsupported micro/greater-equal/plus-minus glyphs in CJK font; appendix uses unambiguous ASCII ug/ml,uM,>=,+/-; raw tables preserve original unicode symbols.','models_run':0,'raw_fetches':0,'old_artifacts_modified':0},indent=2)+'\n')
